const out=[];
const sels=['.crumb a[href="meus-requerimentos.html"]','.crumb span[aria-current]','.dado-resumo','.detalhe-resumo','.etapa-envio .step-info','.etapa-analise .step-info','.etapa-decisao .step-info','.etapa-conclusao .step-info','#aba-andamento','#aba-documentos','td','th','.titulo-duvidas','.duvidas-frequentes .header .title','.header-sign','.rodape-servico .info div','.table-title','caption'];
for(const s of sels){const e=document.querySelector(s); if(!e) {out.push(s+': none');continue;} const c=getComputedStyle(e); let bg='transparent', p=e; while(p){const b=getComputedStyle(p).backgroundColor; if(b!=='rgba(0, 0, 0, 0)'){bg=b;break;} p=p.parentElement;}
out.push([s,c.fontSize,c.fontWeight,c.color,bg,c.fontFamily.slice(0,20),c.opacity, c.lineHeight].join(' | '));}
